import json
from collections import defaultdict

class LogDiagnoser:
    def __init__(self):
        # Dictionary to hold categorized faults
        self.faults = defaultdict(list)

    def parse_plain_text_log(self, log_content):
        """
        Parse plain text log content to identify errors, warnings, and critical events.
        """
        for line in log_content.splitlines():
            line_lower = line.lower()
            if 'error' in line_lower:
                self.faults['Error'].append(line)
            elif 'warning' in line_lower:
                self.faults['Warning'].append(line)
            elif 'critical' in line_lower:
                self.faults['Critical'].append(line)

    def parse_json_log(self, log_content):
        """
        Parse JSON formatted log content to identify errors, warnings, and critical events.
        Assumes log_content is a JSON array of log entries, each with a 'level' and 'message' field.
        """
        try:
            logs = json.loads(log_content)
            for entry in logs:
                level = entry.get('level', '').lower()
                message = entry.get('message', '')
                if level == 'error':
                    self.faults['Error'].append(message)
                elif level == 'warning':
                    self.faults['Warning'].append(message)
                elif level == 'critical':
                    self.faults['Critical'].append(message)
        except json.JSONDecodeError:
            print("Invalid JSON log format.")

    def diagnose(self, log_files):
        """
        Diagnose faults from a list of log files.
        log_files: list of tuples (file_path, format) where format is 'text' or 'json'
        """
        for file_path, fmt in log_files:
            try:
                with open(file_path, 'r') as f:
                    content = f.read()
                    if fmt == 'text':
                        self.parse_plain_text_log(content)
                    elif fmt == 'json':
                        self.parse_json_log(content)
                    else:
                        print(f"Unsupported log format: {fmt} for file {file_path}")
            except FileNotFoundError:
                print(f"Log file not found: {file_path}")

    def generate_report(self):
        """
        Generate a summary report of diagnosed faults.
        """
        report = "Fault Diagnosis Report\n"
        report += "="*25 + "\n"
        for category, messages in self.faults.items():
            report += f"\n{category} - {len(messages)} occurrences\n"
            report += "-"*25 + "\n"
            # Show up to 5 sample messages for each category
            for msg in messages[:5]:
                report += f"- {msg}\n"
            if len(messages) > 5:
                report += f"... and {len(messages) - 5} more\n"
        return report

if __name__ == "__main__":
    # Example usage:
    diagnoser = LogDiagnoser()
    # Provide log files with their format
    logs_to_diagnose = [
        ('equipment_log1.txt', 'text'),
        ('equipment_log2.json', 'json')
    ]
    diagnoser.diagnose(logs_to_diagnose)
    print(diagnoser.generate_report())
```

