The function `openPort` takes the protocol ("tcp" or "udp") and the port number as parameters and sets up a socket to listen for incoming connections or datagrams.

```cpp
#include <iostream>
#include <string>
#include <cstring>      // For memset
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>     // For close()

bool openPort(const std::string& protocol, int port) {
    int sockfd;
    int opt = 1;

    if (protocol != "tcp" && protocol != "udp") {
        std::cerr << "Unsupported protocol: " << protocol << std::endl;
        return false;
    }

    int type = (protocol == "tcp") ? SOCK_STREAM : SOCK_DGRAM;

    sockfd = socket(AF_INET, type, 0);
    if (sockfd < 0) {
        perror("socket");
        return false;
    }

    // Allow reuse of address and port
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(sockfd);
        return false;
    }

    sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    addr.sin_port = htons(port);

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(sockfd);
        return false;
    }

    if (protocol == "tcp") {
        if (listen(sockfd, 5) < 0) {
            perror("listen");
            close(sockfd);
            return false;
        }
        std::cout << "TCP port " << port << " is open and listening." << std::endl;
    } else {
        std::cout << "UDP port " << port << " is open and ready to receive datagrams." << std::endl;
    }

    // For testing purposes, keep the socket open
    // In a real application, you would handle incoming connections or datagrams here

    // To keep the example simple, just sleep or wait here
    std::cout << "Press Enter to close the port and exit..." << std::endl;
    std::cin.get();

    close(sockfd);
    return true;
}

int main() {
    std::string protocol;
    int port;

    std::cout << "Enter protocol (tcp/udp): ";
    std::cin >> protocol;
    std::cout << "Enter port number: ";
    std::cin >> port;

    if (!openPort(protocol, port)) {
        std::cerr << "Failed to open port." << std::endl;
        return 1;
    }

    return 0;
}
```

### Explanation:
- The function `openPort` creates a socket for the specified protocol.
- It sets the socket option `SO_REUSEADDR` to allow quick reuse of the port.
- It binds the socket to the specified port on all network interfaces.
- For TCP, it calls `listen` to start listening for incoming connections.
- For UDP, it just binds the socket to receive datagrams.
- The program waits for the user to press Enter before closing the socket and exiting.

### Notes:
- This code is for Unix-like systems. For Windows, you need to include `<winsock2.h>`, call `WSAStartup` before using sockets, and `WSACleanup` after.
